<?php declare(strict_types=1); namespace Silao\Tests\Unit\Infrastructure\Mapper; use PHPUnit\Framework\TestCase; use Silao\Domain\Booking\Booking; use Silao\Domain\Booking\Enum\QuoteLineType; use Silao\Domain\Booking\ValueObject\BookingId; use Silao\Domain\Booking\ValueObject\BookingReference; use Silao\Domain\Booking\ValueObject\FormDataSnapshot; use Silao\Domain\Booking\ValueObject\Quote; use Silao\Domain\Booking\ValueObject\QuoteLine; use Silao\Domain\Common\ValueObject\Currency; use Silao\Domain\Common\ValueObject\Money; use Silao\Domain\Common\ValueObject\ZonedDateTimeRange; use Silao\Domain\Customer\ValueObject\CustomerId; use Silao\Domain\Customer\ValueObject\CustomerSnapshot; use Silao\Domain\Customer\ValueObject\Email; use Silao\Domain\Customer\ValueObject\PhoneNumber; use Silao\Domain\Model\ValueObject\BookingModelId; use Silao\Domain\Resource\ValueObject\ResourceId; use Silao\Infrastructure\Exception\PersistenceException; use Silao\Infrastructure\Mapper\BookingMapper; use Silao\Infrastructure\Mapper\PriceSnapshotMapper; final class BookingMapperTest extends TestCase { public function testCompleteBookingRoundTrip(): void { $eur = Currency::EUR(); $range = ZonedDateTimeRange::fromIsoStrings("2026-06-15 10:00:00", "2026-06-15 12:00:00", "Europe/Paris"); $cSnap = new CustomerSnapshot(CustomerId::fromString("c1"), Email::fromString("client@example.com"), "John", "Doe", PhoneNumber::fromString("+33 6 12 34 56 78"), false); $booking = new Booking(BookingId::fromString("b_001"), BookingReference::fromString("NEX-001"), $cSnap, BookingModelId::fromString("m1"), ResourceId::fromString("van_1"), $range, new FormDataSnapshot(["passengers" => 3])); $line = new QuoteLine("l1", QuoteLineType::BasePrice, "Transfer", 1, Money::of(10000, $eur), Money::of(10000, $eur)); $quote = new Quote([$line], Money::of(10000, $eur), Money::of(0, $eur), Money::of(0, $eur), Money::of(10000, $eur), $eur); $booking->createQuote($quote); $booking->confirm(); $bookingDbRow = BookingMapper::toDatabase($booking); $priceSnapshot = $booking->priceSnapshot(); $this->assertNotNull($priceSnapshot); $snapshotDbRow = PriceSnapshotMapper::toDatabase("b_001", $priceSnapshot, $booking->quote()); $eventsDbRows = [["event_type" => "booking.created", "occurred_at_utc" => "2026-06-15 08:00:00", "metadata_json" => "[]"], ["event_type" => "booking.quoted", "occurred_at_utc" => "2026-06-15 08:05:00", "metadata_json" => "[]"], ["event_type" => "booking.confirmed", "occurred_at_utc" => "2026-06-15 08:10:00", "metadata_json" => "[]"]]; $hydrated = BookingMapper::toDomain($bookingDbRow, $snapshotDbRow, $eventsDbRows); $this->assertSame("b_001", $hydrated->id()->toString()); $this->assertSame("NEX-001", $hydrated->reference()->toString()); $this->assertTrue($hydrated->status()->isConfirmed()); $this->assertSame("John Doe", $hydrated->customerSnapshot()->fullName()); $this->assertSame("+33 6 12 34 56 78", $hydrated->customerSnapshot()->phone?->toString()); $this->assertSame("van_1", $hydrated->resourceId()?->toString()); $this->assertSame(3, $hydrated->formDataSnapshot()->get("passengers")); $this->assertNotNull($hydrated->priceSnapshot()); $this->assertSame(10000, $hydrated->priceSnapshot()->total->amount); $this->assertCount(3, $hydrated->events()); $this->assertSame("booking.confirmed", $hydrated->events()[2]->type()); } public function testCorruptedFormDataJsonThrowsPersistenceException(): void { $this->expectException(PersistenceException::class); BookingMapper::toDomain(["booking_id" => "b1", "reference" => "REF", "model_id" => "m1", "status" => "draft", "starts_at_utc" => "2026-06-15 10:00:00", "ends_at_utc" => "2026-06-15 12:00:00", "timezone" => "UTC", "customer_snapshot_json" => "{\"customer_id\":\"c1\",\"email\":\"a@b.com\",\"first_name\":\"A\",\"last_name\":\"B\"}", "form_data_json" => "{bad json"]); } }